-- SQL script to create tables for the Anesthesiologist CBT Prep Portal
-- Run this script in the Supabase SQL Editor to enable database storage for packages and attempts.

-- cbt_packages table
create table if not exists public.cbt_packages (
  id text primary key default gen_random_uuid()::text,
  user_id uuid references auth.users(id) on delete cascade,
  name text not null,
  description text,
  created_at timestamptz not null default now(),
  questions jsonb not null -- Stores the 100-question package array directly for efficient serialization and fast Next.js loading
);

-- cbt_attempts table
create table if not exists public.cbt_attempts (
  id text primary key default gen_random_uuid()::text,
  user_id uuid not null references auth.users(id) on delete cascade,
  package_id text not null,
  score numeric not null,
  total_questions int not null,
  correct_count int not null,
  time_spent int not null, -- duration in seconds
  answers jsonb not null, -- maps question index (as string keys) to the selected option
  created_at timestamptz not null default now()
);

-- Enable Row-Level Security
alter table public.cbt_packages enable row level security;
alter table public.cbt_attempts enable row level security;

-- Row-Level Security Policies for cbt_packages
-- 1. Anyone can view packages (both built-in shared ones and custom shared ones)
create policy "packages_select_public" on public.cbt_packages
  for select using (true);

-- 2. Authenticated users can insert their own custom packages
create policy "packages_insert_own" on public.cbt_packages
  for insert with check (auth.uid() = user_id);

-- 3. Authenticated users can delete only their own custom packages
create policy "packages_delete_own" on public.cbt_packages
  for delete using (auth.uid() = user_id);

-- Row-Level Security Policies for cbt_attempts
-- 1. Users can only select/view their own attempts
create policy "attempts_select_own" on public.cbt_attempts
  for select using (auth.uid() = user_id);

-- 2. Users can only insert attempts that belong to themselves
create policy "attempts_insert_own" on public.cbt_attempts
  for insert with check (auth.uid() = user_id);

-- 3. Users can only delete their own attempts
create policy "attempts_delete_own" on public.cbt_attempts
  for delete using (auth.uid() = user_id);

-- Performance Indexes
create index if not exists cbt_packages_user_id_idx on public.cbt_packages(user_id);
create index if not exists cbt_attempts_user_id_idx on public.cbt_attempts(user_id);
create index if not exists cbt_attempts_package_id_idx on public.cbt_attempts(package_id);
create index if not exists cbt_attempts_created_at_idx on public.cbt_attempts(created_at desc);
-- --- SEED DEFAULT QUESTION PACKAGE ---
-- This statement inserts the official 100-question national board practice package into cbt_packages.
insert into public.cbt_packages (id, name, description, questions, user_id)
values (
  'default-national-exam',
  'Paket Try Out Nasional Utama',
  'Paket soal komprehensif 100 soal pilihan ganda (A-E) dalam Bahasa Indonesia untuk mempersiapkan kandidat menghadapi Ujian Nasional Kolegium Anestesiologi dan Terapi Intensif.',
  '[{"id":"q1","text":"Seorang laki-laki berusia 45 tahun dengan riwayat sirosis hepatis Child-Pugh B direncanakan menjalani laparatomi eksplorasi. Terkait pelumpuh otot non-depolarisasi golongan aminosteroid seperti vecuronium, manakah organ eliminasi utama yang bertanggung jawab untuk ekskresi obat ini?","options":{"A":"Ginjal (ekskresi urin primer)","B":"Hati (eliminasi bilier)","C":"Plasma (hidrolisis esterase)","D":"Paru-paru (eliminasi Hofmann)","E":"Kelenjar keringat eksokrin"},"correctOption":"B","category":"Farmakologi & Fisiologi","explanation":"Vecuronium terutama mengalami eliminasi di hati melalui ekskresi bilier (sekitar 40-70%), sedangkan ginjal bertanggung jawab untuk sekitar 20-30% ekskresinya. Pada pasien dengan gangguan fungsi hati, durasi kerja vecuronium dapat memanjang secara signifikan karena penurunan klirens bilier."},{"id":"q2","text":"Seorang primigravida berusia 28 tahun usia kehamilan 38 minggu dengan Preeklamsia Berat (PEB) direncanakan menjalani Sectio Caesarea darurat. Pasien telah mendapatkan terapi loading dose Magnesium Sulfat (MgSO4). Manakah mekanisme fisiologis MgSO4 berikut yang dapat memperpanjang efek obat pelumpuh otot non-depolarisasi?","options":{"A":"Meningkatkan sensitivitas reseptor nikotinik pascasinaps","B":"Meningkatkan sintesis dan pelepasan asetilkolin di presinaps","C":"Menghambat masuknya kalsium pada terminal presinaps sehingga menurunkan pelepasan asetilkolin","D":"Mempercepat metabolisme asetilkolinesterase plasma","E":"Meningkatkan laju filtrasi glomerulus sehingga mempercepat klirens obat"},"correctOption":"C","category":"Anestesi Obstetrik & Pediatrik","explanation":"Magnesium sulfat (MgSO4) bertindak sebagai antagonis kalsium fisiologis di terminal saraf presinaps neuromuscular junction, yang secara signifikan mengurangi influks kalsium dan pelepasan asetilkolin. Kondisi ini meningkatkan kepekaan motor end-plate dan memperpanjang efek blockade pelumpuh otot depolarisasi maupun nondepolarisasi."},{"id":"q3","text":"Seorang laki-laki berusia 30 tahun dibawa ke IGD setelah kecelakaan lalu lintas dengan kecurigaan fraktur kolumna servikal tidak stabil. Pasien mengalami gagal napas akut dan memerlukan intubasi darurat. Manakah tindakan perlindungan jalan napas yang paling direkomendasikan saat laringoskopi?","options":{"A":"Head tilt - Chin lift maksimal","B":"Manuver jaw thrust tanpa alat bantu tambahan","C":"Manual In-Line Stabilization (MILS)","D":"Ekstensi leher dengan menaruh bantal tebal di bawah kepala","E":"Manuver Sellick dengan tekanan krikoid tinggi"},"correctOption":"C","category":"Resusitasi & Critical Care","explanation":"Manual In-Line Stabilization (MILS) adalah standar emas saat intubasi pasien dengan suspek cedera servikal tidak stabil. MILS dilakukan oleh asisten untuk menstabilkan leher secara aksial guna meminimalkan gerakan fleksi-ekstensi kolumna servikal saat laringoskopi dilakukan."},{"id":"q4","text":"Seorang laki-laki berusia 68 tahun dengan riwayat penyakit jantung koroner menjalani operasi TURP dengan anestesi spinal (SAB). Tiga puluh menit setelah injeksi Bupivacaine hiperbarik 12.5 mg, tekanan darah turun menjadi 82/46 mmHg dan laju nadi turun dari 78x/menit menjadi 42x/menit. Manakah dermatom sensorik terblokir yang menjadi penyebab bradikardia ekstrem pada pasien ini?","options":{"A":"Blokade simpatis setinggi dermatom L1-L2","B":"Blokade parasimpatis sakral S2-S4","C":"Blokade serabut simpatis akselerator jantung setinggi T1-T4","D":"Blokade motorik dermatom T10-T12","E":"Efek depresi miokard langsung akibat absorpsi sistemik bupivacaine"},"correctOption":"C","category":"Anestesi Umum & Regional","explanation":"Bradikardia hebat pada blokade spinal tinggi disebabkan oleh terblokirnya serabut simpatis preganglionik T1-T4 (akselerator jantung). Hal ini menyebabkan dominansi tonus vagal dan penurunan venous return (preload) yang memicu penurunan denyut nadi via refleks Bainbridge."},{"id":"q5","text":"Seorang anak laki-laki berusia 6 tahun direncanakan menjalani tonsilektomi. Selama induksi inhalasi menggunakan sevoflurane 8% dalam oksigen 100%, pasien tiba-tiba mengalami rigiditas otot maseter yang berat sehingga mulut tidak dapat dibuka sama sekali untuk intubasi. Manakah kecurigaan komplikasi anestesi utama dan tata laksana darurat pertama yang harus disiapkan?","options":{"A":"Laringospasme berat; berikan propofol 2 mg/kg intravena","B":"Hipertermia Maligna; hentikan sevoflurane dan segera berikan Dantrolene","C":"Kejang mioklonik; berikan Midazolam 0.1 mg/kg intravena","D":"Anafilaksis sevoflurane; berikan Epinefrin 10 mcg/kg intravena","E":"Spasme maseter transient; ganti anestesi dengan isoflurane"},"correctOption":"B","category":"Farmakologi & Fisiologi","explanation":"Rigiditas otot maseter (masseter muscle rigidity - MMR) setelah pemberian zat pemicu (halogenated inhalations atau suksinilkolin) adalah tanda peringatan dini yang sangat kuat dari Hipertermia Maligna. Penanganan utamanya melibatkan penghentian total agen pemicu, hiperventilasi O2 100%, dan pemberian Dantrolene."},{"id":"q6","text":"Pada pemantauan kapnografi intraoperatif pasien dengan ventilasi mekanis, grafik kapnogram menunjukkan penurunan gradual nilai EtCO2 (End-Tidal CO2) mendekati nol disertai hilangnya fase plato alveolar secara mendadak. Penyebab mekanis paling mungkin dari kondisi ini adalah:","options":{"A":"Hiperventilasi alveolar progresif","B":"Ekstubasi tidak sengaja atau diskoneksi sirkuit napas","C":"Rebreathing CO2 karena katup ekspirasi macet","D":"Spasme bronkus parsial","E":"Kebocoran cuff endotrakeal derajat ringan"},"correctOption":"B","category":"Resusitasi & Critical Care","explanation":"Penurunan mendadak nilai EtCO2 mendekati nol dengan hilangnya kurva gelombang secara total biasanya disebabkan oleh kegagalan ventilasi total seperti diskoneksi sirkuit napas, ekstubasi yang tidak disengaja (dislokasi ETT), atau obstruksi total jalan napas."},{"id":"q7","text":"Seorang pasien perempuan berusia 32 tahun, G2P1A0 usia kehamilan 39 minggu, dengan riwayat stenosis katup mitral derajat sedang (mitral stenosis) direncanakan menjalani sectio caesarea. Manakah prinsip manajemen hemodinamik intraoperatif yang PALING tepat untuk pasien ini?","options":{"A":"Mempertahankan denyut jantung sedikit takikardia untuk memaksimalkan cardiac output","B":"Membiarkan hipotensi ringan agar beban kerja ventrikel kiri berkurang","C":"Menghindari takikardia dan menjaga preload yang adekuat serta denyut nadi normal-lambat","D":"Melakukan hidrasi cairan kristaloid agresif (loading 1500 ml) sebelum induksi","E":"Menggunakan agen vasodilatasi murni seperti nitroprusid untuk menurunkan afterload"},"correctOption":"C","category":"Neuroanestesi & Kardiovaskular","explanation":"Pada mitral stenosis, pengisian ventrikel kiri sangat bergantung pada waktu diastolik. Takikardia akan memperpendek waktu diastole sehingga menurunkan curah jantung (cardiac output) secara drastis dan memicu edema paru. Denyut nadi harus dijaga lambat (sinus rhythm) dan fluktuasi cairan dihindari."},{"id":"q8","text":"Seorang neonatus berusia 3 hari dengan diagnosis atresia duodenum dijadwalkan untuk tindakan duodenoduodenostomi darurat. Manakah dari pernyataan berikut yang menggambarkan perbedaan fisiologis sistem pernapasan neonatus dibanding dewasa?","options":{"A":"Neonatus memiliki compliance paru yang sangat tinggi dan compliance dinding dada rendah","B":"Neonatus memiliki fungsional residual capacity (FRC) yang relatif lebih besar dibanding dewasa","C":"Neonatus memiliki konsumsi oksigen per unit berat badan 2-3 kali lebih tinggi dibanding dewasa","D":"Neonatus bernapas dengan otot interkostal sebagai penggerak utama napas","E":"Neonatus memiliki sensitivitas yang sangat rendah terhadap hipoksia dan hiperkapnia"},"correctOption":"C","category":"Anestesi Obstetrik & Pediatrik","explanation":"Konsumsi oksigen neonatus sangat tinggi (sekitar 6-8 mL/kg/menit, dua kali lipat dibanding dewasa) untuk mendukung metabolisme yang cepat. Dikombinasikan dengan kapasitas residu fungsional (FRC) yang rendah, neonatus sangat cepat mengalami desaturasi oksigen (hipoksia) jika terjadi apneu."},{"id":"q9","text":"Seorang perempuan berusia 25 tahun mengeluh nyeri kepala hebat pascaoperasi sectio caesarea dengan anestesi spinal menggunakan jarum Quincke 22G. Nyeri dirasakan memburuk saat posisi tegak/duduk dan membaik bila berbaring terlentang. Manakah terapi definitif paling efektif apabila terapi konservatif gagal mengatasi Post-Dural Puncture Headache (PDPH) pada pasien ini?","options":{"A":"Injeksi metilprednisolon intravena 125 mg","B":"Pemberian kafein oral 500 mg tiga kali sehari","C":"Epidural Blood Patch (EBP) menggunakan darah autolog pasien","D":"Injeksi ketorolac 30 mg intramuskular","E":"Hidrasi cairan kristaloid intravena agresif 200 ml/jam selama 48 jam"},"correctOption":"C","category":"Anestesi Umum & Regional","explanation":"Epidural Blood Patch (EBP) adalah terapi definitif standar emas untuk PDPH parah yang gagal membaik dengan terapi konservatif. Prosedur ini melibatkan penyuntikan 15-20 ml darah autolog steril pasien ke dalam ruang epidural setinggi atau di bawah level pungsi dural sebelumnya untuk menyumbat kebocoran likuor cerebrospinalis."},{"id":"q10","text":"Seorang laki-laki berusia 55 tahun dengan riwayat hipertensi tidak terkontrol menjalani kraniotomi evakuasi hematoma subdural akut. Dokter spesialis anestesi berupaya mengendalikan tekanan perfusi serebral (CPP). Manakah rumus perhitungan tekanan perfusi serebral (CPP) yang benar?","options":{"A":"CPP = MAP + ICP","B":"CPP = MAP - ICP (atau CVP, mana yang lebih tinggi)","C":"CPP = Systolic BP - Diastolic BP","D":"CPP = CVP - ICP","E":"CPP = MAP / ICP"},"correctOption":"B","category":"Neuroanestesi & Kardiovaskular","explanation":"Tekanan Perfusi Serebral (Cerebral Perfusion Pressure - CPP) dihitung menggunakan rumus CPP = MAP - ICP (Mean Arterial Pressure dikurangi Intracranial Pressure). Jika CVP (Central Venous Pressure) lebih tinggi daripada ICP, maka CVP digunakan sebagai pengurang. Nilai CPP normal berkisar antara 60-80 mmHg."},{"id":"q11","text":"Seorang wanita berusia 30 tahun dengan riwayat myasthenia gravis direncanakan menjalani timektomi. Terkait sensitivitas terhadap pelumpuh otot, manakah pernyataan berikut yang PALING tepat?","options":{"A":"Sangat sensitif terhadap pelumpuh otot depolarisasi (suksinilkolin) dan resisten terhadap nondepolarisasi","B":"Resisten terhadap pelumpuh otot depolarisasi dan sangat sensitif terhadap nondepolarisasi","C":"Resisten terhadap kedua jenis pelumpuh otot","D":"Sensitif terhadap kedua jenis pelumpuh otot","E":"Tidak memerlukan pelumpuh otot karena tidak ada reseptor nikotinik"},"correctOption":"B","category":"Farmakologi & Fisiologi","explanation":"Pasien Myasthenia Gravis memiliki jumlah reseptor nikotinik fungsional yang berkurang secara signifikan di NMJ. Oleh karena itu, mereka sangat sensitif terhadap agen nondepolarisasi (memerlukan dosis sangat kecil) dan resisten terhadap suksinilkolin."},{"id":"q12","text":"Selama resusitasi jantung paru pada pasien dewasa dengan henti jantung, berapakah kedalaman kompresi dada eksternal dan laju kompresi yang direkomendasikan oleh panduan AHA?","options":{"A":"Kedalaman minimal 3 cm, laju 80-100 kali/menit","B":"Kedalaman 5-6 cm, laju 100-120 kali/menit","C":"Kedalaman maksimal 7 cm, laju 120-140 kali/menit","D":"Kedalaman 4-5 cm, laju 90-110 kali/menit","E":"Kedalaman minimal 5 cm, laju bebas asalkan kontinu"},"correctOption":"B","category":"Resusitasi & Critical Care","explanation":"RJP berkualitas tinggi untuk pasien dewasa mensyaratkan kedalaman kompresi dada sebesar 5-6 cm (sekitar 2-2.4 inci) dengan laju kompresi 100-120 kali/menit, disertai recoil dada penuh dan interupsi minimal."},{"id":"q13","text":"Manakah dari saraf kranial berikut yang paling sering mengalami cedera paralisis transient sekunder akibat tekanan masker wajah (face mask ventilation) yang terlalu kencang selama induksi anestesi?","options":{"A":"Saraf Kranial VII (Nervus Fasialis - cabang marginal mandibular)","B":"Saraf Kranial V (Nervus Trigeminus)","C":"Saraf Kranial X (Nervus Vagus)","D":"Saraf Kranial XI (Nervus Aksesorius)","E":"Saraf Kranial XII (Nervus Hipoglosus)"},"correctOption":"A","category":"Anestesi Umum & Regional","explanation":"Tekanan masker wajah yang berlebihan pada sudut rahang dapat menekan cabang marginal mandibular dari Nervus Fasialis (saraf kranial VII), menyebabkan kelemahan otot-otot wajah bagian bawah unilateral secara transient pascaoperasi."},{"id":"q14","text":"Seorang bayi baru lahir melalui sectio caesarea karena gawat janin tampak lemas, merintih lambat, denyut jantung 88x/menit, ekstremitas fleksi lemah, dan tubuh merah dengan tungkai biru setelah 1 menit lahir. Berapakah skor APGAR bayi tersebut?","options":{"A":"Skor APGAR 3","B":"Skor APGAR 4","C":"Skor APGAR 5","D":"Skor APGAR 6","E":"Skor APGAR 7"},"correctOption":"C","category":"Anestesi Obstetrik & Pediatrik","explanation":"Kriteria skor APGAR: Denyut Jantung < 100 (1 poin); Upaya Napas merintih/lambat (1 poin); Tonus Otot fleksi lemah (1 poin); Refleks/Gritasi tidak dinilai lengkap tapi merintih lambat (1 poin); Warna Kulit tubuh merah tungkai biru (1 poin). Total skor APGAR = 5 (asfiksia sedang)."},{"id":"q15","text":"Manakah dari target parameter hemodinamik berikut yang harus dipertahankan secara ketat untuk meminimalkan beban kerja miokardium dan risiko iskemia pada pasien dengan stenosis katup aorta selama anestesi umum?","options":{"A":"Menjaga denyut nadi relatif lambat (50-60 bpm) dan menghindari hipotensi sistemik","B":"Membiarkan denyut nadi cepat (90-100 bpm) untuk menjamin curah jantung","C":"Menurunkan resistensi vaskular sistemik (SVR) hingga separuh normal","D":"Membatasi preload cairan seminimal mungkin","E":"Mempertahankan tekanan darah sistolik di bawah 90 mmHg"},"correctOption":"A","category":"Neuroanestesi & Kardiovaskular","explanation":"Pada stenosis aorta, denyut jantung harus dijaga normal-lambat agar waktu diastolik (pengisian arteri koroner) optimal. Hipotensi sistemik sangat berbahaya karena dapat menurunkan tekanan perfusi arteri koroner secara drastis, memicu iskemia miokard sekunder."},{"id":"q16","text":"Seorang wanita berusia 30 tahun dengan riwayat myasthenia gravis direncanakan menjalani timektomi. Terkait sensitivitas terhadap pelumpuh otot, manakah pernyataan berikut yang PALING tepat?","options":{"A":"Sangat sensitif terhadap pelumpuh otot depolarisasi (suksinilkolin) dan resisten terhadap nondepolarisasi","B":"Resisten terhadap pelumpuh otot depolarisasi dan sangat sensitif terhadap nondepolarisasi","C":"Resisten terhadap kedua jenis pelumpuh otot","D":"Sensitif terhadap kedua jenis pelumpuh otot","E":"Tidak memerlukan pelumpuh otot karena tidak ada reseptor nikotinik"},"correctOption":"B","category":"Farmakologi & Fisiologi","explanation":"Pasien Myasthenia Gravis memiliki jumlah reseptor nikotinik fungsional yang berkurang secara signifikan di NMJ. Oleh karena itu, mereka sangat sensitif terhadap agen nondepolarisasi (memerlukan dosis sangat kecil) dan resisten terhadap suksinilkolin."},{"id":"q17","text":"Selama resusitasi jantung paru pada pasien dewasa dengan henti jantung, berapakah kedalaman kompresi dada eksternal dan laju kompresi yang direkomendasikan oleh panduan AHA?","options":{"A":"Kedalaman minimal 3 cm, laju 80-100 kali/menit","B":"Kedalaman 5-6 cm, laju 100-120 kali/menit","C":"Kedalaman maksimal 7 cm, laju 120-140 kali/menit","D":"Kedalaman 4-5 cm, laju 90-110 kali/menit","E":"Kedalaman minimal 5 cm, laju bebas asalkan kontinu"},"correctOption":"B","category":"Resusitasi & Critical Care","explanation":"RJP berkualitas tinggi untuk pasien dewasa mensyaratkan kedalaman kompresi dada sebesar 5-6 cm (sekitar 2-2.4 inci) dengan laju kompresi 100-120 kali/menit, disertai recoil dada penuh dan interupsi minimal."},{"id":"q18","text":"Manakah dari saraf kranial berikut yang paling sering mengalami cedera paralisis transient sekunder akibat tekanan masker wajah (face mask ventilation) yang terlalu kencang selama induksi anestesi?","options":{"A":"Saraf Kranial VII (Nervus Fasialis - cabang marginal mandibular)","B":"Saraf Kranial V (Nervus Trigeminus)","C":"Saraf Kranial X (Nervus Vagus)","D":"Saraf Kranial XI (Nervus Aksesorius)","E":"Saraf Kranial XII (Nervus Hipoglosus)"},"correctOption":"A","category":"Anestesi Umum & Regional","explanation":"Tekanan masker wajah yang berlebihan pada sudut rahang dapat menekan cabang marginal mandibular dari Nervus Fasialis (saraf kranial VII), menyebabkan kelemahan otot-otot wajah bagian bawah unilateral secara transient pascaoperasi."},{"id":"q19","text":"Seorang bayi baru lahir melalui sectio caesarea karena gawat janin tampak lemas, merintih lambat, denyut jantung 88x/menit, ekstremitas fleksi lemah, dan tubuh merah dengan tungkai biru setelah 1 menit lahir. Berapakah skor APGAR bayi tersebut?","options":{"A":"Skor APGAR 3","B":"Skor APGAR 4","C":"Skor APGAR 5","D":"Skor APGAR 6","E":"Skor APGAR 7"},"correctOption":"C","category":"Anestesi Obstetrik & Pediatrik","explanation":"Kriteria skor APGAR: Denyut Jantung < 100 (1 poin); Upaya Napas merintih/lambat (1 poin); Tonus Otot fleksi lemah (1 poin); Refleks/Gritasi tidak dinilai lengkap tapi merintih lambat (1 poin); Warna Kulit tubuh merah tungkai biru (1 poin). Total skor APGAR = 5 (asfiksia sedang)."},{"id":"q20","text":"Manakah dari target parameter hemodinamik berikut yang harus dipertahankan secara ketat untuk meminimalkan beban kerja miokardium dan risiko iskemia pada pasien dengan stenosis katup aorta selama anestesi umum?","options":{"A":"Menjaga denyut nadi relatif lambat (50-60 bpm) dan menghindari hipotensi sistemik","B":"Membiarkan denyut nadi cepat (90-100 bpm) untuk menjamin curah jantung","C":"Menurunkan resistensi vaskular sistemik (SVR) hingga separuh normal","D":"Membatasi preload cairan seminimal mungkin","E":"Mempertahankan tekanan darah sistolik di bawah 90 mmHg"},"correctOption":"A","category":"Neuroanestesi & Kardiovaskular","explanation":"Pada stenosis aorta, denyut jantung harus dijaga normal-lambat agar waktu diastolik (pengisian arteri koroner) optimal. Hipotensi sistemik sangat berbahaya karena dapat menurunkan tekanan perfusi arteri koroner secara drastis, memicu iskemia miokard sekunder."},{"id":"q21","text":"Seorang wanita berusia 30 tahun dengan riwayat myasthenia gravis direncanakan menjalani timektomi. Terkait sensitivitas terhadap pelumpuh otot, manakah pernyataan berikut yang PALING tepat?","options":{"A":"Sangat sensitif terhadap pelumpuh otot depolarisasi (suksinilkolin) dan resisten terhadap nondepolarisasi","B":"Resisten terhadap pelumpuh otot depolarisasi dan sangat sensitif terhadap nondepolarisasi","C":"Resisten terhadap kedua jenis pelumpuh otot","D":"Sensitif terhadap kedua jenis pelumpuh otot","E":"Tidak memerlukan pelumpuh otot karena tidak ada reseptor nikotinik"},"correctOption":"B","category":"Farmakologi & Fisiologi","explanation":"Pasien Myasthenia Gravis memiliki jumlah reseptor nikotinik fungsional yang berkurang secara signifikan di NMJ. Oleh karena itu, mereka sangat sensitif terhadap agen nondepolarisasi (memerlukan dosis sangat kecil) dan resisten terhadap suksinilkolin."},{"id":"q22","text":"Selama resusitasi jantung paru pada pasien dewasa dengan henti jantung, berapakah kedalaman kompresi dada eksternal dan laju kompresi yang direkomendasikan oleh panduan AHA?","options":{"A":"Kedalaman minimal 3 cm, laju 80-100 kali/menit","B":"Kedalaman 5-6 cm, laju 100-120 kali/menit","C":"Kedalaman maksimal 7 cm, laju 120-140 kali/menit","D":"Kedalaman 4-5 cm, laju 90-110 kali/menit","E":"Kedalaman minimal 5 cm, laju bebas asalkan kontinu"},"correctOption":"B","category":"Resusitasi & Critical Care","explanation":"RJP berkualitas tinggi untuk pasien dewasa mensyaratkan kedalaman kompresi dada sebesar 5-6 cm (sekitar 2-2.4 inci) dengan laju kompresi 100-120 kali/menit, disertai recoil dada penuh dan interupsi minimal."},{"id":"q23","text":"Manakah dari saraf kranial berikut yang paling sering mengalami cedera paralisis transient sekunder akibat tekanan masker wajah (face mask ventilation) yang terlalu kencang selama induksi anestesi?","options":{"A":"Saraf Kranial VII (Nervus Fasialis - cabang marginal mandibular)","B":"Saraf Kranial V (Nervus Trigeminus)","C":"Saraf Kranial X (Nervus Vagus)","D":"Saraf Kranial XI (Nervus Aksesorius)","E":"Saraf Kranial XII (Nervus Hipoglosus)"},"correctOption":"A","category":"Anestesi Umum & Regional","explanation":"Tekanan masker wajah yang berlebihan pada sudut rahang dapat menekan cabang marginal mandibular dari Nervus Fasialis (saraf kranial VII), menyebabkan kelemahan otot-otot wajah bagian bawah unilateral secara transient pascaoperasi."},{"id":"q24","text":"Seorang bayi baru lahir melalui sectio caesarea karena gawat janin tampak lemas, merintih lambat, denyut jantung 88x/menit, ekstremitas fleksi lemah, dan tubuh merah dengan tungkai biru setelah 1 menit lahir. Berapakah skor APGAR bayi tersebut?","options":{"A":"Skor APGAR 3","B":"Skor APGAR 4","C":"Skor APGAR 5","D":"Skor APGAR 6","E":"Skor APGAR 7"},"correctOption":"C","category":"Anestesi Obstetrik & Pediatrik","explanation":"Kriteria skor APGAR: Denyut Jantung < 100 (1 poin); Upaya Napas merintih/lambat (1 poin); Tonus Otot fleksi lemah (1 poin); Refleks/Gritasi tidak dinilai lengkap tapi merintih lambat (1 poin); Warna Kulit tubuh merah tungkai biru (1 poin). Total skor APGAR = 5 (asfiksia sedang)."},{"id":"q25","text":"Manakah dari target parameter hemodinamik berikut yang harus dipertahankan secara ketat untuk meminimalkan beban kerja miokardium dan risiko iskemia pada pasien dengan stenosis katup aorta selama anestesi umum?","options":{"A":"Menjaga denyut nadi relatif lambat (50-60 bpm) dan menghindari hipotensi sistemik","B":"Membiarkan denyut nadi cepat (90-100 bpm) untuk menjamin curah jantung","C":"Menurunkan resistensi vaskular sistemik (SVR) hingga separuh normal","D":"Membatasi preload cairan seminimal mungkin","E":"Mempertahankan tekanan darah sistolik di bawah 90 mmHg"},"correctOption":"A","category":"Neuroanestesi & Kardiovaskular","explanation":"Pada stenosis aorta, denyut jantung harus dijaga normal-lambat agar waktu diastolik (pengisian arteri koroner) optimal. Hipotensi sistemik sangat berbahaya karena dapat menurunkan tekanan perfusi arteri koroner secara drastis, memicu iskemia miokard sekunder."},{"id":"q26","text":"Seorang wanita berusia 30 tahun dengan riwayat myasthenia gravis direncanakan menjalani timektomi. Terkait sensitivitas terhadap pelumpuh otot, manakah pernyataan berikut yang PALING tepat?","options":{"A":"Sangat sensitif terhadap pelumpuh otot depolarisasi (suksinilkolin) dan resisten terhadap nondepolarisasi","B":"Resisten terhadap pelumpuh otot depolarisasi dan sangat sensitif terhadap nondepolarisasi","C":"Resisten terhadap kedua jenis pelumpuh otot","D":"Sensitif terhadap kedua jenis pelumpuh otot","E":"Tidak memerlukan pelumpuh otot karena tidak ada reseptor nikotinik"},"correctOption":"B","category":"Farmakologi & Fisiologi","explanation":"Pasien Myasthenia Gravis memiliki jumlah reseptor nikotinik fungsional yang berkurang secara signifikan di NMJ. Oleh karena itu, mereka sangat sensitif terhadap agen nondepolarisasi (memerlukan dosis sangat kecil) dan resisten terhadap suksinilkolin."},{"id":"q27","text":"Selama resusitasi jantung paru pada pasien dewasa dengan henti jantung, berapakah kedalaman kompresi dada eksternal dan laju kompresi yang direkomendasikan oleh panduan AHA?","options":{"A":"Kedalaman minimal 3 cm, laju 80-100 kali/menit","B":"Kedalaman 5-6 cm, laju 100-120 kali/menit","C":"Kedalaman maksimal 7 cm, laju 120-140 kali/menit","D":"Kedalaman 4-5 cm, laju 90-110 kali/menit","E":"Kedalaman minimal 5 cm, laju bebas asalkan kontinu"},"correctOption":"B","category":"Resusitasi & Critical Care","explanation":"RJP berkualitas tinggi untuk pasien dewasa men